INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Farbtiefe dasselbe wie die Bildauflösung?', 2, '[{"text": "No", "correct": true, "because": "Bits vs. Pixelanzahl"}, {"text": "Yes", "correct": false, "because": "Different concepts"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of color depth?', 3, '[{"text": "Determine color range per pixel", "correct": true, "because": "Color representation"}, {"text": "Increase screen size", "correct": false, "because": "Not resolution"}, {"text": "Enhance network speed", "correct": false, "because": "Not network-related"}]'),
('00000000-0000-0000-0000-000000000000', 'Which values are common for color depth?', 5, '[{"text": "8-bit", "correct": true, "because": "256 colors"}, {"text": "24-bit", "correct": true, "because": "16.7 million colors"}, {"text": "1-meter", "correct": false, "because": "Not a measure"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) Higher color depth means more colors. b) It reduces image quality.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Improves quality"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore with color depth?', 4, '[{"text": "Bit count", "correct": false, "because": "Defines depth"}, {"text": "Color range", "correct": false, "because": "Core aspect"}, {"text": "Paper weight", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if color depth affects file size?', 2, '[{"text": "Yes", "correct": true, "because": "More bits, larger files"}, {"text": "No", "correct": false, "because": "Direct impact"}]'),
('00000000-0000-0000-0000-000000000000', 'Which color depth is known as "True Color"?', 3, '[{"text": "24-bit", "correct": true, "because": "16.7 million colors"}, {"text": "8-bit", "correct": false, "because": "256 colors"}, {"text": "1-bit", "correct": false, "because": "Monochrome"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does higher color depth offer?', 5, '[{"text": "Better color accuracy", "correct": true, "because": "More shades"}, {"text": "Smoother gradients", "correct": true, "because": "Less banding"}, {"text": "Faster processing", "correct": false, "because": "Not speed-related"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) 16-bit color depth supports thousands of colors. b) It’s only for black-and-white images. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Not monochrome"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for color depth?', 4, '[{"text": "Bits per pixel", "correct": false, "because": "Defines depth"}, {"text": "Display support", "correct": false, "because": "Hardware requirement"}, {"text": "Physical size", "correct": true, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Is 1-bit color depth used for color images?', 2, '[{"text": "No", "correct": true, "because": "Monochrome only"}, {"text": "Yes", "correct": false, "because": "Black and white"}]'),
('00000000-0000-0000-0000-000000000000', 'Which systems use color depth?', 4, '[{"text": "Monitors", "correct": true, "because": "Display colors"}, {"text": "Graphics cards", "correct": true, "because": "Process colors"}, {"text": "Keyboards", "correct": false, "because": "Input device"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that color depth doesn’t affect image quality. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Higher depth improves quality"}, {"text": "Yes", "correct": false, "because": "Direct impact"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize with color depth?', 3, '[{"text": "Color accuracy", "correct": true, "because": "Visual quality"}, {"text": "Paper type", "correct": false, "because": "Irrelevant"}, {"text": "Speed", "correct": false, "because": "Quality focus"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) 32-bit color depth includes transparency. b) It’s only for printers.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Also displays"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What factors influence color depth?', 5, '[{"text": "Bits per channel", "correct": true, "because": "RGB definition"}, {"text": "Hardware support", "correct": true, "because": "Display capability"}, {"text": "Paper thickness", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for color depth?', 3, '[{"text": "Bit allocation", "correct": false, "because": "Defines range"}, {"text": "Color channels", "correct": false, "because": "RGB structure"}, {"text": "Font style", "correct": true, "because": "No impact"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does 8-bit color depth support millions of colors?', 3, '[{"text": "No", "correct": true, "because": "Only 256 colors"}, {"text": "Yes", "correct": false, "because": "24-bit needed"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if color depth impacts storage requirements?', 2, '[{"text": "Yes", "correct": true, "because": "More bits, more space"}, {"text": "No", "correct": false, "because": "Direct correlation"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to color depth?', 4, '[{"text": "Bits per pixel", "correct": true, "because": "Core definition"}, {"text": "Physical dimensions", "correct": false, "because": "Not relevant"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
